for K=[{pt(k1)} {pt(k2)} {pt(k3)}]
	M=feedback(K*bg,1);
	[NumM,DenM]=tfdata(M, 'v');
	raicesDenM=roots(DenM);
	x=x+1;
	polos(x,1:2)=raicesDenM';
end
